from pathlib import Path
from html import escape
import base64
P=Path(__file__).parent
def bi(tag,es,en,attrs=''):
 return f'<{tag} {attrs} data-es="{escape(es,quote=True)}" data-en="{escape(en,quote=True)}">{escape(es)}</{tag}>'
def para(es,en,cls=''):return bi('p',es,en,f'class="{cls}"')
def radio(name,es,en,options):
 return '<fieldset>'+bi('legend',es,en)+''.join('<label class="choice"><input type="radio" name="'+name+'" value="'+value+'">'+bi('span',s,e)+'</label>' for value,s,e in options)+'</fieldset>'
def inp(name,es,en,default=''):
 return '<label class="field">'+bi('span',es,en)+f'<input name="{name}" inputmode="decimal" autocomplete="off" maxlength="12" value="{default}" placeholder="0.00"></label>'
def button(id,es,en,cls='gold'):return bi('button',es,en,f'id="{id}" class="{cls}" type="button"')
steps=[('La solicitud','The request'),('El presupuesto','The estimate'),('Tu respuesta','Your reply'),('El cambio','The change'),('Tu revisión','Your review')]
introES='Bienvenido al Laboratorio de Trabajo Bilingüe de Plutón Academic. Aquí practicas casos de trabajo: entiendes a un cliente, preparas un presupuesto y respondes en inglés. Después revisas tus decisiones y descubres qué mejorar. Empieza con nuestro primer caso y convierte lo aprendido en una habilidad que puedas usar. Tu futuro comienza con conocimiento.'
introEN='Welcome to Plutón Academic’s Bilingual Work Lab. Here you practice workplace cases: understand a client, prepare an estimate and respond in English. Then review your decisions and discover what to improve. Start with our first case and turn learning into a skill you can use. Your future begins with knowledge.'
stages=[]
stages.append(para('COMPRENDE ANTES DE PROMETER','UNDERSTAND BEFORE YOU PROMISE','eyebrow')+bi('h2','Lee el mensaje de Alex.','Read Alex’s message.')+'''<div class="email"><div class="emailhead"><span class="avatar">AM</span><div><b>Alex Morgan</b>'''+bi('small','Cliente del caso de práctica','Practice case client')+'''</div></div><p lang="en">Hello! Could you send me an estimate for standard cleaning of our small office? Friday at 9:00 a.m. would work for us. Our budget is up to $160. We do not need exterior windows or oven cleaning. Please let me know what is included and whether you are available. Thank you!</p><details>'''+bi('summary','Ver apoyo en español','View Spanish support')+'<p lang="es">Hola. Solicito un presupuesto de limpieza estándar de una oficina pequeña. Nos serviría el viernes a las 9:00. El máximo es $160. No necesitamos ventanas exteriores ni interior del horno. Indique qué incluye y si tiene disponibilidad.</p></details></div>'+radio('scope','¿Qué servicio se solicita?','What service is requested?',[('standard','Limpieza estándar, sin ventanas exteriores ni horno','Standard cleaning, excluding exterior windows and oven'),('everything','Limpieza completa con todos los extras','Full cleaning with every extra')])+radio('schedule','¿El horario ya está reservado?','Is the time already booked?',[('requested','No: falta confirmar disponibilidad','No: availability must be confirmed'),('confirmed','Sí: mencionar la hora confirma la reserva','Yes: mentioning the time confirms the booking')])+radio('budget','¿Qué representa $160?','What does $160 represent?',[('limit','El máximo indicado por el cliente','The maximum budget stated by the client'),('charge','El precio obligatorio, aunque el cálculo sea menor','The required price, even if our estimate is lower')]))
stages.append(para('CALCULA CON CRITERIO','CALCULATE WITH CARE','eyebrow')+bi('h2','Ponle números al servicio.','Put numbers to the service.')+para('Añade un recargo del 25% sobre el costo total. Todos los importes están en USD.','Add a 25% surcharge to the total cost. All amounts are in USD.')+'<div class="costs">'+''.join('<div>'+bi('small',s,e)+f'<b>{v}</b></div>' for s,e,v in [('Mano de obra','Labor','4 h × $22'),('Materiales','Materials','$12'),('Transporte','Travel','$10'),('Recargo sobre costo','Surcharge on cost','25%')])+'</div><div class="formrow">'+inp('cost','Costo total antes del recargo (USD)','Total cost before surcharge (USD)')+inp('total','Presupuesto final (USD)','Final estimate (USD)')+'</div>'+para('Recargo sobre costo: costo × 1.25. Un margen del 25% sobre venta usaría otra fórmula.','Surcharge on cost: cost × 1.25. A 25% margin on sales would use a different formula.','hint')+'<details class="calculator">'+bi('summary','Abrir calculadora de apoyo','Open practice calculator')+'<div class="calcfields">'+''.join(inp(n,s,e,v) for n,s,e,v in [('calcHours','Horas','Hours','4'),('calcRate','Costo por hora','Hourly cost','22'),('calcMaterials','Materiales','Materials','12'),('calcTravel','Transporte','Travel','10'),('calcMarkup','Recargo %','Surcharge %','25')])+'</div>'+button('calculate','Calcular','Calculate','navy')+'<p id="calculation" role="status"></p></details>')
stages.append(para('COMUNICA SIN PROMETER DE MÁS','COMMUNICATE WITHOUT OVERPROMISING','eyebrow')+bi('h2','Construye tu respuesta en inglés.','Build your reply in English.')+para('El borrador refleja tus decisiones, incluso si necesitan corrección.','The draft reflects your decisions, even when they need correction.')+radio('reply','¿Cómo presentas el importe?','How do you present the amount?',[('estimate','Our estimate for standard office cleaning is…','Our estimate for standard office cleaning is…'),('booking','Your booking is confirmed at…','Your booking is confirmed at…')])+radio('status','¿Qué dices del horario?','What do you say about the time?',[('ask','Friday at 9:00 is subject to availability.','Friday at 9:00 is subject to availability.'),('guarantee','We guarantee Friday at 9:00.','We guarantee Friday at 9:00.')])+bi('h3','Tu borrador de práctica','Your practice draft')+'<pre id="draft" lang="en"></pre><label class="field">'+bi('span','Escribe tu propia versión o una nota (opcional)','Write your own version or a note (optional)')+'<textarea name="notes" rows="5" maxlength="3000"></textarea></label>'+para('Este texto libre no se califica automáticamente. Compáralo con el ejemplo explicado al terminar.','This free text is not automatically graded. Compare it with the explained example when you finish.','hint'))
stages.append(para('CUANDO EL CLIENTE CAMBIA EL PLAN','WHEN THE CLIENT CHANGES THE PLAN','eyebrow')+bi('h2','Un extra cambia los números.','An extra changes the numbers.')+'<div class="email"><b>Alex Morgan</b><p lang="en">Could you also clean the inside of the oven? I would still like to stay within $160 if possible.</p>'+para('El extra necesita una hora más a $22. Materiales y transporte no cambian. Mantén el recargo del 25% sobre costo.','The extra needs one more hour at $22. Materials and travel stay the same. Keep the 25% surcharge on cost.')+'</div>'+inp('revised','Nuevo presupuesto con el extra (USD)','Revised estimate including the extra (USD)')+radio('change','¿Qué haces antes de aceptar?','What do you do before accepting?',[('approve','Explico el nuevo precio y pido aprobación; ofrezco conservar el alcance original','Explain the revised price and ask for approval; offer to keep the original scope'),('absorb','Acepto el extra sin hablar del precio','Accept the extra without discussing the price'),('silent','Cambio el precio y confirmo la reserva sin consultar','Change the price and confirm the booking without asking')]))
stages.append(para('TU TRABAJO, CON PERSPECTIVA','YOUR WORK, IN PERSPECTIVE','eyebrow')+bi('h2','Cada decisión te enseña algo.','Every decision teaches you something.')+'<div class="scorecard"><div><strong id="score">0</strong><span>/100</span></div>'+para('Puntuación de práctica con criterios visibles. Puedes volver y corregir.','Practice score with visible criteria. You can go back and revise.')+'</div><div id="feedback"></div><details class="model">'+bi('summary','Ver la respuesta modelo y explicación','View the model answer and explanation')+para('Costo inicial $110; recargo $27.50; presupuesto $137.50. Con el extra, costo $132 y presupuesto $165: supera el límite por $5.','Initial cost $110; surcharge $27.50; estimate $137.50. With the extra, cost $132 and estimate $165: $5 over budget.')+'<pre lang="en">Dear Alex,\nOur estimate for standard office cleaning is $137.50, excluding exterior windows and oven cleaning. Friday at 9:00 is subject to availability.\n\nAdding oven cleaning brings the estimate to $165.00. This is $5.00 above your stated budget. Would you like to approve the revised scope and price, or keep the original service? We will confirm availability before booking.\n\nKind regards,\nYour service team</pre></details><div class="reportactions">'+button('export','Descargar mi informe TXT ↓','Download my TXT report ↓')+button('print','Imprimir borrador / guardar PDF','Print draft / save PDF','navy')+'</div>'+para('Guardar PDF depende del diálogo de impresión del navegador. No es un certificado profesional.','PDF saving depends on the browser’s print dialog. This is not a professional certificate.','hint')+'<details>'+bi('summary','Leer mi informe completo','Read my full report')+'<pre id="report"></pre></details>')
html='''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>B88 · Laboratorio de Trabajo Bilingüe · PLUTÓN ACADEMIC</title><link rel="stylesheet" href="styles.css"><script src="engine.js" defer></script><script src="app.js" defer></script></head><body>'''
html+='<div class="reviewbar"><i></i>'+bi('span','B88 · PRUEBA PRIVADA','B88 · PRIVATE REVIEW')+bi('span','Proyecto para revisión · sin pagos','Project for review · no payments')+'</div><header><a class="brand" href="#portada"><span class="planet">◉</span><span>PLUTÓN <b>ACADEMIC</b>'+bi('small','LABORATORIO DE TRABAJO BILINGÜE','BILINGUAL WORK LAB')+'</span></a>'+button('lang','EN ↗','ES ↗','language')+'</header><main id="portada"><section id="overview"><div class="hero"><div>'+para('DEL CONOCIMIENTO A LA PRÁCTICA','FROM KNOWLEDGE TO PRACTICE','eyebrow')+bi('h1','Practica hoy.\nTrabaja con más confianza.','Practice today.\nWork with more confidence.')+para('Un cliente. Una decisión. Una oportunidad para hacerlo mejor. Resuelve un caso de trabajo en español e inglés, paso a paso.','One client. One decision. One chance to improve. Work through a Spanish–English workplace case, step by step.','lead')+'<div class="actions">'+button('start','Entrar al primer caso →','Start the first case →')+bi('a','Conoce el laboratorio ↓','Meet the lab ↓','href="#presentacion" class="quiet"')+'</div>'+para('Práctica gratuita en esta muestra · Sin registro · Respuestas solo en esta pestaña','Free practice in this preview · No sign-up · Answers stay in this tab','small muted')+'</div><aside class="cover"><div class="coverline">'+para('CASO 01','CASE 01','eyebrow')+bi('span','10–15 minutos','10–15 minutes','class="pill"')+'</div><div class="caseart" aria-hidden="true"><div class="orbit"></div><div class="paper"><small>PLUTÓN LAB</small><b>ESTIMATE</b><i></i><i></i><i></i><strong>$ —</strong></div><span class="badge">ES ↔ EN</span></div>'+bi('h2','Tu primer cliente.\nTu mejor respuesta.','Your first client.\nYour best response.')+para('Atención al cliente y presupuesto de servicios','Customer service and a service estimate','muted')+'<div class="coverfooter">'+bi('span','5 etapas','5 stages')+bi('span','Decisiones + cálculos + revisión','Decisions + calculations + review')+'</div></aside></div><div class="benefits">'+''.join('<div><span>0'+str(i+1)+'</span>'+bi('h3',s,e)+para(ps,pe)+'</div>' for i,(s,e,ps,pe) in enumerate([('Comprende','Understand','Identifica lo que se pide y lo que falta por confirmar.','Identify the request and what still needs confirmation.'),('Resuelve','Solve','Calcula, comunica y responde a un cambio de alcance.','Calculate, communicate and respond to a scope change.'),('Mejora','Improve','Revisa criterios claros y descarga tu informe.','Review clear criteria and download your report.')]))+'</div><section class="presentation" id="presentacion"><div>'+para('UNA BIENVENIDA DE TU INSTRUCTOR','A WELCOME FROM YOUR INSTRUCTOR','eyebrow')+bi('h2','Aquí se aprende haciendo.','Learn by doing, right here.')+para('Presentación corta en español con el avatar y la voz aprobados del fundador.','Short Spanish introduction using the founder’s approved avatar and voice.')+'<details>'+bi('summary','Leer transcripción ES/EN','Read ES/EN transcript')+para(introES,introEN)+'</details></div><div class="videobox"><video id="introVideo" controls playsinline preload="metadata" src="presentacion.mp4" poster="presentacion-poster.jpg" aria-label="Presentación en español de PLUTÓN ACADEMIC"></video>'+para('Presentación · 22 segundos · No inicia automáticamente','Introduction · 22 seconds · Does not play automatically','small muted')+'</div></section></section>'
html+='<section id="workspace" hidden aria-labelledby="workTitle"><div class="workheading"><div>'+para('CASO 01 · SERVICIOS','CASE 01 · SERVICES','eyebrow')+bi('h1','Un cliente espera tu respuesta.','A client is waiting for your reply.','id="workTitle" tabindex="-1"')+'</div>'+button('reset','Reiniciar caso','Restart case','outline')+'</div>'+para('Caso ficticio de aprendizaje. No envía mensajes ni crea reservas. Se califican decisiones e importes; no la gramática del texto libre.','Fictional learning case. No messages or bookings are created. Scoring uses decisions and amounts, not free-text grammar.','notice')+'<div id="resetBox" class="confirm" role="alert" hidden>'+para('¿Borrar las respuestas de este caso? No se puede deshacer.','Clear this case’s answers? This cannot be undone.')+button('confirmReset','Sí, borrar respuestas','Yes, clear answers')+button('cancelReset','Conservar mi trabajo','Keep my work','outline')+'</div><div class="workgrid"><aside class="workflow">'+para('TU RECORRIDO','YOUR PATH','eyebrow')+'<nav aria-label="Etapas / Stages">'+''.join('<button type="button" data-jump="'+str(i)+'" '+('disabled' if i else '')+'><span>0'+str(i+1)+'</span>'+bi('b',s,e)+'</button>' for i,(s,e) in enumerate(steps))+'</nav><div class="progress"><span id="stepLabel"></span><div role="progressbar" id="progressBar" aria-label="Progreso / Progress" aria-valuemin="0" aria-valuemax="5" aria-valuenow="1"><i></i></div></div>'+para('Puedes volver para corregir. Cerrar o recargar esta pestaña borra las respuestas.','You can go back to revise. Closing or reloading this tab clears the answers.','small muted')+'</aside><div class="desk"><form id="caseForm" novalidate>'+''.join('<section class="stage" data-step="'+str(i)+'" '+('hidden' if i else '')+'>'+s+'</section>' for i,s in enumerate(stages))+'</form><div class="stepactions">'+button('previous','← Anterior','← Previous','outline')+'<p id="status" role="status" aria-live="polite"></p>'+button('next','Continuar →','Continue →')+'</div></div></div></section><noscript>Activa JavaScript para probar el caso. / Enable JavaScript to try the case.</noscript><section id="printSheet"></section></main><footer><span>◉ PLUTÓN ACADEMIC</span>'+para('Tu futuro comienza con conocimiento.','Your future begins with knowledge.')+bi('small','B88 · Proyecto en revisión · Sin cobros','B88 · Project under review · No payments')+'</footer></body></html>'
(P/'index.html').write_text(html)
print('HTML fuente B88 generado.')
